#include <stdio.h>

static inline int read_int(void) {
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) c = getchar_unlocked();

    int value = 0;
    while (c >= '0' && c <= '9') {
        value = value * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return value;
}

int main(void) {
    int n = read_int();
    long long *a = malloc((size_t)n * sizeof(long long));

    for (int i = 0; i < n; i++)
        a[i] = read_int();

    int left = 0, right = n - 1;
    long long left_sum = a[left], right_sum = a[right];
    int operations = 0;

    while (left < right) {
        if (left_sum == right_sum) {
            left++;
            right--;
            if (left < right) {
                left_sum = a[left];
                right_sum = a[right];
            }
        } else if (left_sum < right_sum) {
            left++;
            left_sum += a[left];
            operations++;
        } else {
            right--;
            right_sum += a[right];
            operations++;
        }
    }

    printf("%d\n", operations);
    free(a);
    return 0;
}
